mapper.select:
SELECT t1.*, t2.nickname AS applicantName, t3.nickname AS auditorName, t4.amount AS originalAmount, t4.record_category AS originalCategory FROM tb_reversal_application t1 LEFT JOIN tb_user t2 ON t1.applicant_user_id = t2.id LEFT JOIN tb_user t3 ON t1.auditor_id = t3.id LEFT JOIN tb_record_detail t4 ON t1.original_record_id = t4.id WHERE t1.record_book_id = #{recordBookId} AND t1.delete_time IS NULL
AND t1.audit_status = #{auditStatus}
ORDER BY t1.create_time DESC
